 10	package com.example.domain.entity;
 11	
 12	import com.example.domain.enums.OrderStatus;
 13	import jakarta.persistence.*;
 14	import java.math.BigDecimal;
 15	import java.time.Instant;
 16	import java.util.ArrayList;
 17	import java.util.List;
 18	import java.util.UUID;
 19	
 20	@Entity
 21	@Table(name = "orders")
 22	public class Order {
 23	
 24	    @Id
 25	    private String id;
 26	
 27	    @Column(nullable = false, length = 11)
 28	    private String customerCpf;
 29	
 30	    @Column(nullable = false, length = 100)
 31	    private String customerEmail;
 32	
 33	    @Column(nullable = false)
 34	    @Enumerated(EnumType.STRING)
 35	    private OrderStatus status;
 36	
 37	    @Column(nullable = false)
 38	    private Instant createdAt;
 39	
 40	    @Column
 41	    private Instant paidAt;
 42	
 43	    @Column
 44	    private String lastSuccessfulTransactionId;
 45	
 46	    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
 47	    @JoinColumn(name = "order_id")
 48	    private List<OrderItem> items = new ArrayList<>();
 49	
 50	    @Column(nullable = false)
 51	    @Convert(converter = OrderSummaryConverter.class)
 52	    private OrderSummary summary;
 53	
 54	    @Column
 55	    private String trackingCode;
 56	
 57	    protected Order() {
 58	    }
 59	
 60	    public Order(String customerCpf, String customerEmail, OrderSummary summary) {
 61	        this.id = UUID.randomUUID().toString();
 62	        this.customerCpf = customerCpf;
 63	        this.customerEmail = customerEmail;
 64	        this.status = OrderStatus.AWAITING_PAYMENT;
 65	        this.createdAt = Instant.now();
 66	        this.summary = summary;
 67	    }
 68	
 69	    public String getId() {
 70	        return id;
 71	    }
 72	
 73	    public String getCustomerCpf() {
 74	        return customerCpf;
 75	    }
 76	
 77	    public String getCustomerEmail() {
 78	        return customerEmail;
 79	    }
 80	
 81	    public OrderStatus getStatus() {
 82	        return status;
 83	    }
 84	
 85	    public Instant getCreatedAt() {
 86	        return createdAt;
 87	    }
 88	
 89	    public Instant getPaidAt() {
 90	        return paidAt;
 91	    }
 92	
 93	    public List<OrderItem> getItems() {
 94	        return items;
 95	    }
 96	
 97	    public OrderSummary getSummary() {
 98	        return summary;
 99	    }
100	
101	    public String getTrackingCode() {
102	        return trackingCode;
103	    }
104	
105	    public void addItem(OrderItem item) {
106	        this.items.add(item);
107	    }
108	
109	    public void setStatus(OrderStatus status) {
110	        this.status = status;
111	    }
112	
113	    public void setPaidAt(Instant paidAt) {
114	        this.paidAt = paidAt;
115	    }
116	
117	    public void setTrackingCode(String trackingCode) {
118	        this.trackingCode = trackingCode;
119	    }
120	
121	    public String getLastSuccessfulTransactionId() {
122	        return lastSuccessfulTransactionId;
123	    }
124	
125	    public void setLastSuccessfulTransactionId(String transactionId) {
126	        this.lastSuccessfulTransactionId = transactionId;
127	    }
128	
129	    public boolean isPaidWithinTimeout(long timeoutMillis) {
130	        if (this.paidAt == null) {
131	            return false;
132	        }
133	        long elapsed = this.paidAt.toEpochMilli() - this.createdAt.toEpochMilli();
134	        return elapsed <= timeoutMillis;
135	    }
136	}
